import React, { useState, useEffect } from 'react';

const navLinks = ['About', 'Skills', 'Projects', 'Services', 'Contact'];

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <nav style={{
      position: 'fixed', top: 0, left: 0, right: 0, zIndex: 100,
      background: scrolled ? 'rgba(10,10,10,0.95)' : 'rgba(10,10,10,0.7)',
      backdropFilter: 'blur(12px)',
      borderBottom: '1px solid rgba(255,107,26,0.15)',
      padding: '0 5%',
      transition: 'background 0.3s'
    }}>
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        height: 60, maxWidth: 1100, margin: '0 auto'
      }}>
        <div style={{ fontWeight: 800, fontSize: '1.1rem', letterSpacing: '-0.02em' }}>
          B<span style={{ color: 'var(--orange)' }}>.</span>Amare
        </div>
        <ul style={{ display: 'flex', gap: '2rem', listStyle: 'none' }}>
          {navLinks.map(link => (
            <li key={link}>
              <a
                href={`#${link.toLowerCase()}`}
                style={{
                  color: 'var(--muted)', textDecoration: 'none',
                  fontSize: '0.8rem', letterSpacing: '0.08em',
                  textTransform: 'uppercase', transition: 'color 0.2s'
                }}
                onMouseEnter={e => e.target.style.color = 'var(--orange)'}
                onMouseLeave={e => e.target.style.color = 'var(--muted)'}
              >
                {link}
              </a>
            </li>
          ))}
        </ul>
        <a href="#contact" className="btn-primary" style={{ fontSize: '0.75rem', padding: '8px 20px' }}>
          Hire Me
        </a>
      </div>
    </nav>
  );
}
